import { createCipheriv, createDecipheriv, createHash, randomBytes, randomInt } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, renameSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { DEMO_PEOPLE, type DemoPersonKey } from "./demoAtelierIdentity.js";

/**
 * Local demo credentials. Operator PINs are generated per root, kept in the
 * root (never in Git) and never regenerated by preparation. Backup bundles
 * carry them only sealed with a per-user local key that lives outside both
 * the root and the backups.
 */

export const DEMO_ATELIER_SECRETS = "demo-atelier-secrets.json";

export type DemoSecretsFile = {
  schemaVersion: 1;
  createdAt: string;
  operatorPins: Record<DemoPersonKey, string>;
};

export type DemoSecrets = {
  operatorPin(person: DemoPersonKey): string;
};

function generatePin(): string {
  // 8 digits, first digit non-zero; never a shared constant.
  return String(randomInt(10_000_000, 100_000_000));
}

export function generateDemoSecrets(): DemoSecretsFile {
  const pins = new Set<string>();
  const operatorPins = {} as Record<DemoPersonKey, string>;
  for (const person of DEMO_PEOPLE) {
    let pin = generatePin();
    while (pins.has(pin)) pin = generatePin();
    pins.add(pin);
    operatorPins[person.key] = pin;
  }
  return { schemaVersion: 1, createdAt: new Date().toISOString(), operatorPins };
}

export function demoSecretsPath(root: string): string {
  return join(root, DEMO_ATELIER_SECRETS);
}

/** Writes once. Refuses to replace existing credentials. */
export function writeNewDemoSecrets(root: string, secrets: DemoSecretsFile): void {
  const path = demoSecretsPath(root);
  if (existsSync(path)) {
    throw new Error("demo_secrets_exist");
  }
  const temp = `${path}.tmp`;
  writeFileSync(temp, `${JSON.stringify(secrets, null, 2)}\n`, { mode: 0o600 });
  renameSync(temp, path);
}

export function readDemoSecretsFile(root: string): DemoSecretsFile | null {
  const path = demoSecretsPath(root);
  if (!existsSync(path)) return null;
  const parsed = JSON.parse(readFileSync(path, "utf8")) as DemoSecretsFile;
  if (parsed.schemaVersion !== 1 || !parsed.operatorPins) {
    throw new Error("demo_secrets_incompatible");
  }
  return parsed;
}

export function secretsAccess(file: DemoSecretsFile): DemoSecrets {
  return {
    operatorPin(person) {
      const pin = file.operatorPins[person];
      if (!pin) throw new Error(`demo_secret_missing:${person}`);
      return pin;
    },
  };
}

export function loadDemoSecrets(root: string): DemoSecrets {
  const file = readDemoSecretsFile(root);
  if (!file) {
    throw new Error("demo_secrets_missing: run credentials-init (existing root) or init (new root)");
  }
  return secretsAccess(file);
}

// --- Local key for sealing credentials inside backup bundles -----------------

export const DEMO_KEY_NAME = "demo-atelier-n019.key";

export function defaultDemoKeyRoot(env: NodeJS.ProcessEnv = process.env): string {
  const override = env.WORKOS_DEMO_ATELIER_KEY_ROOT?.trim();
  if (override) return override;
  const base =
    process.platform === "win32"
      ? env.LOCALAPPDATA?.trim() || join(homedir(), "AppData", "Local")
      : env.XDG_DATA_HOME?.trim() || join(homedir(), ".local", "share");
  return join(base, "WorkOS", "demo-atelier-keys");
}

/** Reads the local sealing key, creating it once (32 random bytes, user-only file). */
export function ensureDemoKey(keyRoot: string): { key: Buffer; keyId: string } {
  mkdirSync(keyRoot, { recursive: true });
  const path = join(keyRoot, DEMO_KEY_NAME);
  if (!existsSync(path)) {
    writeFileSync(path, randomBytes(32).toString("base64"), { mode: 0o600, flag: "wx" });
  }
  return readDemoKey(keyRoot);
}

export function readDemoKey(keyRoot: string): { key: Buffer; keyId: string } {
  const path = join(keyRoot, DEMO_KEY_NAME);
  if (!existsSync(path)) {
    throw new Error(`demo_key_missing:${path}`);
  }
  const key = Buffer.from(readFileSync(path, "utf8").trim(), "base64");
  if (key.length !== 32) throw new Error("demo_key_invalid");
  return { key, keyId: createHash("sha256").update(key).digest("hex").slice(0, 16) };
}

export type SealedBlob = { alg: "aes-256-gcm"; keyId: string; iv: string; tag: string; ciphertext: string };

export function sealJson(value: unknown, key: { key: Buffer; keyId: string }): SealedBlob {
  const iv = randomBytes(12);
  const cipher = createCipheriv("aes-256-gcm", key.key, iv);
  const ciphertext = Buffer.concat([cipher.update(JSON.stringify(value), "utf8"), cipher.final()]);
  return {
    alg: "aes-256-gcm",
    keyId: key.keyId,
    iv: iv.toString("base64"),
    tag: cipher.getAuthTag().toString("base64"),
    ciphertext: ciphertext.toString("base64"),
  };
}

export function unsealJson<T>(blob: SealedBlob, key: { key: Buffer; keyId: string }): T {
  if (blob.alg !== "aes-256-gcm" || blob.keyId !== key.keyId) {
    throw new Error("demo_sealed_key_mismatch");
  }
  const decipher = createDecipheriv("aes-256-gcm", key.key, Buffer.from(blob.iv, "base64"));
  decipher.setAuthTag(Buffer.from(blob.tag, "base64"));
  const plain = Buffer.concat([decipher.update(Buffer.from(blob.ciphertext, "base64")), decipher.final()]);
  return JSON.parse(plain.toString("utf8")) as T;
}
